/// <summary>
/// CB129 Cancellation of Open SO/PO lines
/// </summary>
internal final class METSalesCancelService extends SysOperationServiceBase
{
    ReasonCode              reasonCode;
    METOrderExtractStatus   extractedStatus;
    container               salesLineCon;

}

Method.Source:
/// <summary>
/// The process method for the back orders processing
/// </summary>
/// <param name = "_contract">The data contract object</param>
public void processOperation(METSalesCancelContract _contract)
{ 
    int i = 0;
    boolean errorAllowSalesBackOrder = false;

    reasonCode = _contract.parmReasonCode();
    extractedStatus = _contract.parmExtractedStatus();
    salesLineCon = _contract.parmSalesLineRecords();

    [errorAllowSalesBackOrder, i] = this.cancelBackOrderLines();

    str infoMessage = strFmt(literalStr("@MET:LinesCancelled"), i);

    if (errorAllowSalesBackOrder)
    {
        throw error("@MET:CancelErr" + METConstants::space + infoMessage);
    }

    info(infoMessage);
}

/// <summary>
/// Cancel backorder lines
/// </summary>
/// <returns>container with false if any errors; otherwise true and the number of sales line cancelled</returns>
container cancelBackOrderLines()
{
    Query query;
    QueryRun queryRun;
    int i = 0;
    SalesLine salesLine;
    boolean error = false;
    METSalesLine metSalesLine;

    // Build the query
    query = this.buildQuery();

    queryRun = new QueryRun(query);

    while (queryRun.next())
    {
        // get salesLine to cancel
        salesLine = queryRun.get(tableNum(SalesLine));

        try
        {
            ttsbegin;
            setPrefix(strFmt(METConstants::CancelLinePrefix, salesLine.SalesId, salesLine.ItemId, salesLine.LineNum));

            // cancel the salesLine
            salesLine.metCancelSalesOrderLine();
            metSalesLine = metSalesLine::find(salesLine.RecId,true);
            if(metSalesLine)
            {
                metSalesLine.ReasonId = reasonCode;
                metSalesLine.update();
            }
            i++;
            ttscommit;
        }
        // If any errors continue to the next line to cancel
        catch (Exception::Error)
        {
            error = true;
        }
    }

    return [error, i];
}

/// <summary>
/// Build query to cancel sales lines
/// </summary>
/// <returns>Query object</returns>
Query buildQuery()
{
    QueryBuildDataSource qbdsSalesLine, qbdsMETSalesLine;

    Query query = new Query(queryStr(METSalesLineCancel));

    qbdsSalesLine = query.dataSourceTable(tableNum(SalesLine));

    qbdsMETSalesLine = query.dataSourceTable(tablenum(METSalesLine));

    QueryBuildRange qbrSalesLines = qbdsSalesLine.addRange(fieldnum(SalesLine, RecId));
    qbrSalesLines.value(con2Str(salesLineCon));

    if (extractedStatus)
    {
        qbdsMETSalesLine.addRange(fieldNum(METSalesLine, OrderExtractStatus)).value(queryValue(extractedStatus));
    }
    return query;
}
